import {demoMedia} from './catalog.js';
import {configureSourceSearch,loadSourceOptions,sourceSearchView,initializeSourceSearch} from './source-search.js';
import {DEFAULT_SETTINGS,filterMedia,toggleCompare,validateSettings,statusNames,progressOf,bytes} from './core.js';

const serverMode=!!document.querySelector('meta[name="cinevault-server"]');
const csrfToken=()=>document.querySelector('meta[name="csrf-token"]')?.content||'';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={compass:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18Z M16 8l-2.5 5.5L8 16l2.5-5.5L16 8Z',compare:'M8 3v18 M16 3v18 M3 8l5-5 5 5 M11 16l5 5 5-5',download:'M12 3v12 M7 10l5 5 5-5 M4 15v5h16v-5',settings:'m9 3-1 3-3 1-2 3 2 2v3l2 2 3-1 2 2 3-1 1-3 3-1 1-3-2-2V5l-3-1-2 1-3-2Z M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8Z',film:'M4 3h16v18H4V3Z M8 3v18 M16 3v18 M4 8h4 M4 16h4 M16 8h4 M16 16h4',chevron:'m9 6 6 6-6 6',help:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18Z M9.5 9a2.5 2.5 0 1 1 4 2c-1.5 1-1.5 1.5-1.5 3 M12 17h.01',lock:'M6 10h12v11H6V10Z M8 10V6a4 4 0 0 1 8 0v4 M12 14v3',menu:'M4 6h16 M4 12h16 M4 18h16',refresh:'M20 10a8 8 0 0 0-14-5L3 8 M3 3v5h5 M4 14a8 8 0 0 0 14 5l3-3 M21 21v-5h-5',arrow:'M4 12h16 M15 7l5 5-5 5',star:'m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9L12 3Z',sparkles:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3Z',folder:'M3 6h7l2 3h9v11H3V6Z',check:'m5 12 4 4L19 6',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18Z M12 7v5l3 2',search:'M10.5 3a7.5 7.5 0 1 0 0 15 7.5 7.5 0 0 0 0-15Z M16 16l5 5',grid:'M3 3h7v7H3V3Z M14 3h7v7h-7V3Z M3 14h7v7H3v-7Z M14 14h7v7h-7v-7Z',list:'M8 5h13 M8 12h13 M8 19h13 M3 5h.01 M3 12h.01 M3 19h.01',plus:'M12 5v14 M5 12h14',link:'m10 14 4-4 M8 16l-2 2a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0 M16 8l2-2a4 4 0 0 1 6 6l-5 5a4 4 0 0 1-6 0',info:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18Z M12 11v6 M12 7h.01',close:'m6 6 12 12 M18 6 6 18',pause:'M8 5v14 M16 5v14',play:'m7 4 14 8-14 8V4Z',trash:'M4 6h16 M9 6V3h6v3 M6 6l1 15h10l1-15 M10 10v7 M14 10v7',external:'M14 3h7v7 M21 3 10 14 M10 3H3v18h18v-7',copy:'M8 8h13v13H8V8Z M16 8V3H3v13h5',server:'M3 3h18v7H3V3Z M3 14h18v7H3v-7Z M7 6.5h.01 M7 17.5h.01',heart:'M12 20S2 14 2 8a5 5 0 0 1 10-1A5 5 0 0 1 22 8c0 6-10 12-10 12Z'};
const icon=(n,cls='')=>`<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.info}"/></svg>`;
function hydrate(){document.querySelectorAll('[data-icon]').forEach(e=>{e.innerHTML=icon(e.dataset.icon);e.removeAttribute('data-icon');});document.querySelectorAll('img').forEach(i=>{i.addEventListener('error',()=>i.remove(),{once:true});if(i.complete&&i.naturalWidth===0)i.remove();});}
function read(key,fallback){try{return JSON.parse(localStorage.getItem('cinevault-'+key))??fallback;}catch{return fallback;}}
function save(key,v){try{localStorage.setItem('cinevault-'+key,JSON.stringify(v));}catch{toast('浏览器存储不可用，本次更改仅在当前页面生效');}}
let settings={...DEFAULT_SETTINGS,...read('settings',{})},media=[...demoMedia],selected=read('compare',[]).filter(id=>demoMedia.some(m=>m.id===id)).slice(0,4),tasks=read('tasks',[]),live=serverMode,view='discover',listView=false,downloadFilter='',lastSync=null,crawlError='',crawlFailure=null,respectRobots=true,isCrawling=false;
let filters={search:'',type:'',genre:'',minRating:settings.minRating,year:'',quality:'',sort:'rating'};
let previousFocus=null,modalMovie=null;
const routeLabels={discover:'资源发现',sources:'多来源检索',compare:'内容比较',downloads:'下载任务',settings:'目录与设置'};
function toast(message,error=false){const e=document.createElement('div');e.className='toast'+(error?' error':'');e.textContent=message;$('#toasts').append(e);setTimeout(()=>e.remove(),4500);}
async function api(path,method='GET',body){const c=new AbortController(),timer=setTimeout(()=>c.abort(),path.startsWith('/downloads/')?45000:path==='/sync/latest/download'?170000:path.endsWith('/magnets')?45000:path==='/crawl'?95000:path==='/search'?80000:path.startsWith('/resources/archive/')?27000:15000);try{const r=await fetch('/api'+path,{method,headers:{...(body?{'Content-Type':'application/json'}:{}),...(!['GET','HEAD'].includes(method)?{'X-CineVault-Request':'1','X-CSRF-TOKEN':csrfToken()}:{})},body:body?JSON.stringify(body):undefined,signal:c.signal});if(r.status===401&&serverMode){location.assign('/account/login?returnUrl='+encodeURIComponent(location.pathname+location.hash));throw new Error('请重新登录');}if(!(r.headers.get('content-type')||'').includes('json'))throw new Error('未检测到本地 MVC 服务');const data=await r.json();if(!r.ok)throw Object.assign(new Error(data.error||data.title||'请求失败'),data);return data;}finally{clearTimeout(timer);}}
function poster(m,extra=''){return `<div class="poster ${extra}" style="--poster-color:${esc(m.color||'#65765b')}"><div class="poster-fallback">${esc(m.title)}<small>${esc(m.originalTitle||'CINEVAULT COLLECTION')}</small></div>${m.poster?`<img src="${esc(m.poster)}" alt="${esc(m.title)}海报" loading="lazy" referrerpolicy="no-referrer">`:''}</div>`;}
function heading(title,sub,actions=''){return `<div class="page-heading"><div><div class="eyebrow">YOUR PERSONAL CINEMA</div><h1>${title}</h1><p>${sub}</p></div><div class="heading-actions">${actions}</div></div>`;}
function updateCounts(){const active=tasks.filter(t=>['Queued','Downloading','Retrying','Paused'].includes(t.status)).length;$('#task-count').textContent=active;$('#compare-count').textContent=selected.length;$('#service-text').innerHTML=live?'本地服务已连接<small>ASP.NET Core MVC · 就绪</small>':'交互演示模式<small>连接本地服务以开始下载</small>';$('#footer-mode').textContent=live?'本地服务 · 检索结果与资源库':'示例内容 · 评分与资源仅用于交互演示';}
function render(){view=location.hash.slice(1).split('?')[0]||'discover';if(!routeLabels[view])view='discover';document.querySelectorAll('[data-nav]').forEach(e=>e.classList.toggle('active',e.dataset.nav===view));$('#breadcrumb-current').textContent=routeLabels[view];$('#sidebar').classList.remove('open');updateCounts();$('#app').innerHTML=view==='sources'?sourceSearchView(heading,live):view==='discover'?discoverView():view==='compare'?compareView():view==='downloads'?downloadsView():settingsView();hydrate();renderDock();}
function sourceWarning(){if(!crawlError)return '';const labels={robots_disallowed:'源站限制自动抓取',source_tls_error:'源站证书校验失败',source_timeout:'源站请求超时',source_network_error:'源站连接失败',source_address_blocked:'容器解析地址受限',source_dns_error:'容器域名解析失败',source_domain_parked:'源站当前为域名停放页',source_access_denied:'源站拒绝访问',source_rate_limited:'源站请求频率受限',source_parse_empty:'源站页面未能解析'};return `<div class="notice warning">${icon('info')}<div><strong>${esc(labels[crawlFailure?.code]||'抓取未完成')}</strong><p>${esc(crawlError)}</p>${crawlFailure?.hint?`<p class="muted">${esc(crawlFailure.hint)}</p>`:''}<div class="heading-actions">${crawlFailure?.robotsUrl?`<a class="btn small" href="${esc(safeUrl(crawlFailure.robotsUrl))}" target="_blank" rel="noopener noreferrer">查看访问规则 ${icon('external')}</a>`:''}<button class="btn small" data-action="manual-download">手动添加下载链接</button></div></div></div>`;}
function discoverView(){const high=media.filter(m=>m.rating>=8).length,completed=tasks.filter(t=>t.status==='Completed').length;return `${heading('好内容，值得收藏。','发现高分佳作，比较优质资源，构建你的私人影库。',`<button class="btn" data-action="help">${icon('info')}使用指南</button><button class="btn primary ${isCrawling?'spin':''}" data-action="crawl" ${isCrawling?'disabled':''}>${icon('refresh')}${isCrawling?'正在抓取':'检索新资源'}</button>`)}
<section class="hero" aria-label="精选高分内容"><div class="hero-copy"><span class="hero-label">${icon('sparkles')} 每一个好故事，都值得被珍藏</span><h2>穿越银幕，<br>遇见<em>值得收藏的世界。</em></h2><p>从经典电影到口碑剧集，按你的标准发现好内容。</p><button class="btn lime" data-action="high-rated">探索高分片单 ${icon('arrow')}</button></div><div class="hero-visual" aria-hidden="true">${[demoMedia[4],demoMedia[1],demoMedia[2]].map(m=>`<div class="hero-poster" style="background:${m.color}"><img src="${m.poster}" alt="" referrerpolicy="no-referrer"><span class="hero-film-label">${m.originalTitle}</span></div>`).join('')}<span class="hero-tag">${icon('star')}好故事，<b>高分见</b></span></div></section>
<div class="summary-row"><div class="stat"><span class="stat-icon">${icon('film')}</span><div><div class="stat-label">收录资源</div><div class="stat-value">${media.length}<small style="font-size:10px;font-weight:400;margin-left:4px">部</small></div></div><span class="stat-hint">${live?'已抓取':'示例片单'}</span></div><div class="stat"><span class="stat-icon">${icon('star')}</span><div><div class="stat-label">8 分以上佳作</div><div class="stat-value">${high}<small style="font-size:10px;font-weight:400;margin-left:4px">部</small></div></div><span class="stat-hint">精挑细选</span></div><div class="stat"><span class="stat-icon">${icon('download')}</span><div><div class="stat-label">进行中的任务</div><div class="stat-value" id="stat-active">${tasks.filter(t=>['Downloading','Queued','Retrying'].includes(t.status)).length}<small style="font-size:10px;font-weight:400;margin-left:4px">个</small></div></div><span class="stat-hint">有序下载</span></div><div class="stat"><span class="stat-icon">${icon('check')}</span><div><div class="stat-label">已完成下载</div><div class="stat-value" id="stat-complete">${completed}<small style="font-size:10px;font-weight:400;margin-left:4px">个</small></div></div><span class="stat-hint">${live?'本地保存':'模拟任务'}</span></div></div>
<section id="library"><div class="section-heading"><h2>发现你的下一部佳作 <span>THE COLLECTION</span></h2><span class="subtle-label">${icon('clock')}${live?(lastSync?'最近更新 '+new Date(lastSync).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'}):'等待首次抓取'):'精编示例片单'}</span></div>
${sourceWarning()}
<div class="search-filter"><div class="search-row"><div class="tabs" role="tablist" aria-label="内容类型">${[['','全部内容'],['movie','电影'],['tv','电视剧']].map(([v,l])=>`<button class="tab ${filters.type===v?'active':''}" role="tab" aria-selected="${filters.type===v}" data-type="${v}">${l}<span>${v?media.filter(m=>m.type===v).length:media.length}</span></button>`).join('')}</div><label class="searchbox">${icon('search')}<input id="search" type="search" aria-label="搜索影片名称、类型" placeholder="搜索片名、英文名、类型…" value="${esc(filters.search)}"><span style="font-size:9px;opacity:.5">↵</span></label></div>
<div class="filters"><label class="filter-field">类型<select data-filter="genre" aria-label="影片类型">${options(['','剧情','科幻','冒险','悬疑','犯罪','喜剧','动画','奇幻','历史'],filters.genre,'全部类型')}</select></label><label class="filter-field">评分<span class="rating-filter"><input id="rating-filter" data-filter="minRating" aria-label="最低评分" type="range" min="0" max="9.5" step="0.5" value="${filters.minRating}"><output id="rating-output">${Number(filters.minRating).toFixed(1)}+</output></span></label><label class="filter-field">年份<select data-filter="year" aria-label="发行年份">${options(['',...[...new Set(media.map(m=>m.year))].sort((a,b)=>b-a)],filters.year,'全部年份')}</select></label><label class="filter-field">画质<select data-filter="quality" aria-label="资源画质">${options(['','4K','1080P','720P'],filters.quality,'全部画质')}</select></label><button class="reset-btn" data-action="reset">${icon('refresh')}重置筛选</button></div></div>
<div class="list-toolbar"><span id="result-count"></span><div class="toolbar-right"><select data-filter="sort" aria-label="排序方式">${[['latest','最新上映优先'],['rating','来源评分优先'],['imdb','IMDb 评分优先'],['year','最新年份优先'],['title','名称排序']].map(([v,l])=>`<option value="${v}" ${filters.sort===v?'selected':''}>${l}</option>`).join('')}</select><div class="view-switch" aria-label="显示方式"><button class="${!listView?'active':''}" data-view="grid" aria-label="网格显示" aria-pressed="${!listView}">${icon('grid')}</button><button class="${listView?'active':''}" data-view="list" aria-label="列表显示" aria-pressed="${listView}">${icon('list')}</button></div></div></div><div class="movie-grid ${listView?'list-view':''}" id="movie-grid"></div>
<div class="sample-note">${icon('info')}<span>${live?'资料来自已连接的电影来源；磁力资源按片名、年份、画质及字幕标注排序。':'当前为示例片单，评分、画质与体积均为交互演示数据，未从源站验证。'} <button data-action="source">查看数据来源</button></span></div></section>`;}
function options(arr,value,empty){return arr.map(v=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(v||empty)}</option>`).join('');}
function renderCards(){if(view!=='discover')return;const items=filterMedia(media,filters);$('#result-count').innerHTML=`共 <strong>${items.length}</strong> 部内容 <span style="margin-left:7px">${live?'':'· 示例片单'}</span>`;$('#movie-grid').className='movie-grid'+(listView?' list-view':'');$('#movie-grid').innerHTML=items.length?items.map(m=>`<article class="movie-card" data-movie="${esc(m.id)}" tabindex="0" role="button" aria-label="查看${esc(m.title)}资源"><div class="poster" style="--poster-color:${esc(m.color||'#627b5b')}"><div class="poster-fallback">${esc(m.title)}<small>${esc(m.originalTitle)}</small></div>${m.poster?`<img src="${esc(m.poster)}" alt="${esc(m.title)}海报" loading="lazy" referrerpolicy="no-referrer">`:''}<div class="poster-top"><span class="quality-badge">${m.qualities.includes('4K')?'4K UHD':esc(m.qualities[0]||'待解析')}</span><button class="compare-toggle ${selected.includes(m.id)?'selected':''}" data-compare="${esc(m.id)}" aria-pressed="${selected.includes(m.id)}" aria-label="${selected.includes(m.id)?'移出':'加入'}比较：${esc(m.title)}">${icon(selected.includes(m.id)?'check':'plus')}</button></div><div class="poster-bottom"><span class="score">${icon('star')}${m.rating?m.rating.toFixed(1):'暂无'}</span><span class="tag">${esc(m.tag||m.source||'源站资源')}</span></div></div><div class="card-info"><h3 class="movie-title">${esc(m.title)}</h3><div class="movie-meta"><span>${esc(m.year||'未知年份')}</span><span class="dot">·</span><span>${m.type==='tv'?'电视剧':m.type==='movie'?'电影':'类别未知'}</span><span class="dot">·</span><span>${esc(m.genres.slice(0,2).join(' / ')||'未分类')}</span></div><div class="card-footer"><span>${icon('link')}${m.isDemo?'示例资源':m.resources?.length+' 个资源'}</span><button class="card-link" data-details="${esc(m.id)}">查看资源 ${icon('chevron')}</button></div></div></article>`).join(''):`<div class="empty" style="grid-column:1/-1">${icon('search')}<h3>${live&&!media.length?'从第一次发现开始':'还没有找到匹配的内容'}</h3><p>${live&&!media.length?'点击「检索新资源」查询 Internet Archive、TMDB 等来源。':'试试其他片名，或放宽评分、年份和画质条件。'}</p><button class="btn" data-action="${live&&!media.length?'crawl':'reset'}">${live&&!media.length?'检索新资源':'重置筛选'}</button></div>`;hydrate();}
function renderDock(){updateCounts();const chosen=selected.map(id=>media.find(m=>m.id===id)).filter(Boolean);$('#compare-dock').innerHTML=chosen.length&&view==='discover'?`<div class="compare-dock"><span>已选 <strong>${chosen.length}</strong> / 4 部</span><div class="dock-thumbs">${chosen.map(m=>`<span class="dock-thumb">${esc(m.title.slice(0,2))}${m.poster?`<img src="${esc(m.poster)}" alt="${esc(m.title)}">`:''}<button data-compare="${esc(m.id)}" aria-label="移除${esc(m.title)}">×</button></span>`).join('')}</div><a href="#compare" class="btn primary">${icon('compare')}开始比较</a><button class="icon-btn" data-action="clear-compare" aria-label="清空比较">${icon('close')}</button></div>`:'';hydrate();}
function compareView(){const chosen=selected.map(id=>media.find(m=>m.id===id)).filter(Boolean);return heading('好内容，放在一起看。','并排比较评分、类型与画质，找到最适合收藏的那一部。',`<a href="#discover" class="btn">${icon('plus')}继续添加</a>${chosen.length?'<button class="btn" data-action="clear-compare">清空比较</button>':''}`)+(!chosen.length?`<div class="empty">${icon('compare')}<h3>让选择更简单一点</h3><p>在资源卡片右上角点击「+」，最多可选 4 部内容进行比较。</p><a href="#discover" class="btn primary">去发现内容 ${icon('arrow')}</a></div>`:`<div class="notice">${icon('info')}<span>${live?'评分按各自来源独立展示。':'以下为示例数据。豆瓣与 IMDb 评分各有统计口径，供并排参考。'}</span></div><div class="compare-table-wrap"><table class="compare-table"><tbody><tr><th>比较内容<br><small>${chosen.length} / 4 部</small></th>${chosen.map(m=>`<td>${m.poster?`<img src="${esc(m.poster)}" alt="${esc(m.title)}海报">`:''}<h3>${esc(m.title)}</h3><small>${esc(m.originalTitle)}</small><button class="compare-remove" data-compare="${esc(m.id)}">${icon('close')} 移出比较</button></td>`).join('')}</tr>${[[live?'来源评分':'豆瓣评分',m=>`<span class="rating-large">${m.rating?m.rating.toFixed(1):'—'}</span> <small>/ 10 · ${esc(m.ratingSource||'源站')}</small>`],['IMDb 评分',m=>`<span class="rating-large">${m.imdb?m.imdb.toFixed(1):'—'}</span> <small>/ 10</small>`],['类型',m=>esc(m.genres.join(' / ')||'未知')],['内容类别',m=>m.type==='tv'?'电视剧':m.type==='movie'?'电影':'类别未知'],['发行年份',m=>esc(m.year||'未知')],['时长 / 集数',m=>esc(m.duration||'源站未提供')],['资源画质',m=>esc(m.qualities.join(' · ')||'未解析')],['数据来源',m=>m.isDemo?'交互演示数据':`<a class="resource-link" href="${esc(safeUrl(m.sourceUrl))}" target="_blank" rel="noopener noreferrer">查看源站 ${icon('external')}</a>`],['资源选择',m=>`<button class="btn primary small" data-details="${esc(m.id)}">${icon('download')}查看资源</button>`]].map(([label,fn])=>`<tr><th>${label}</th>${chosen.map(m=>`<td class="${(label==='豆瓣评分'||label==='源站评分')&&m.rating===Math.max(...chosen.map(x=>x.rating))?'best':''}">${fn(m)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`);}
function downloadsView(){return heading('收藏，在路上。','跟踪每一项下载，暂停、继续，或让失败的任务再试一次。',`<button class="btn" data-action="retry-all">${icon('refresh')}重试失败</button><button class="btn primary" data-action="manual-download">${icon('plus')}新建任务</button>`)+`${!live?`<div class="notice warning">${icon('info')}<span>演示队列：进度与状态均为模拟，不会向目录写入文件。选择 4K 示例资源可体验首次失败与自动重试。</span></div>`:''}<div class="task-section-head"><div class="tabs download-tabs">${[['','全部任务'],['active','进行中'],['Completed','已完成'],['Failed','失败']].map(([v,l])=>`<button class="tab ${downloadFilter===v?'active':''}" data-task-filter="${v}">${l} <span>${v==='active'?tasks.filter(t=>['Queued','Downloading','Paused','Retrying'].includes(t.status)).length:v?tasks.filter(t=>t.status===v).length:tasks.length}</span></button>`).join('')}</div><button class="btn small" data-action="clear-completed">${icon('trash')}清理已结束记录</button></div><div class="download-list" id="download-list">${downloadCards()}</div><div class="directory-strip">${icon('folder')}<span>默认保存至</span><code>${esc(settings.directory)}</code><a href="#settings" class="btn small">更改目录 ${icon('chevron')}</a></div>`;}
function downloadCards(){const visible=tasks.filter(t=>!downloadFilter||downloadFilter==='active'&&['Queued','Downloading','Paused','Retrying'].includes(t.status)||t.status===downloadFilter);return visible.length?visible.map(t=>{const p=progressOf(t),m=media.find(m=>m.id===t.mediaId);return `<article class="download-card ${esc(t.status)}">${m?.poster?`<div class="download-poster"><img src="${esc(m.poster)}" alt=""></div>`:''}<div class="download-body"><div class="download-title"><h3>${esc(t.title)} ${t.isDemo?'<span class="demo-badge">模拟</span>':''}</h3><span class="status-pill ${esc(t.status)}">${statusNames[t.status]||esc(t.status)}</span></div><div class="download-sub"><span>${esc(t.quality||'HTTP')} · ${esc(t.fileName)}</span><span>重试 ${t.attempts||0} / ${t.maxRetries??settings.maxRetries}</span></div><div class="progress-track"><div class="progress-fill" style="width:${p}%"></div></div><div class="download-progress"><span>${t.totalBytes?`${bytes(t.bytesReceived)} / ${bytes(t.totalBytes)}`:t.isDemo?`${p}% · 模拟进度`:bytes(t.bytesReceived)+' / 大小未知'}${t.status==='Downloading'&&t.speed?' · '+bytes(t.speed)+'/s':''}</span><span>${esc(t.directory)}</span></div>${t.error?`<div class="task-error">${esc(t.error)}</div>`:''}</div><div class="download-actions">${['Downloading','Queued','Retrying'].includes(t.status)?`<button class="icon-btn" data-task-action="pause" data-task="${esc(t.id)}" aria-label="暂停${esc(t.title)}" title="暂停">${icon('pause')}</button>`:''}${t.status==='Paused'?`<button class="icon-btn" data-task-action="resume" data-task="${esc(t.id)}" aria-label="继续${esc(t.title)}" title="继续">${icon('play')}</button>`:''}${['Failed','Cancelled'].includes(t.status)?`<button class="icon-btn" data-task-action="retry" data-task="${esc(t.id)}" aria-label="重试${esc(t.title)}" title="重试">${icon('refresh')}</button>`:''}${!['Completed','Cancelled'].includes(t.status)?`<button class="icon-btn" data-task-action="cancel" data-task="${esc(t.id)}" aria-label="取消${esc(t.title)}" title="取消">${icon('close')}</button>`:''}${t.isDemo&&t.status==='Downloading'?`<button class="icon-btn" data-task-action="fail" data-task="${esc(t.id)}" aria-label="模拟下载失败" title="模拟下载失败">${icon('info')}</button>`:''}</div></article>`;}).join(''):`<div class="empty">${icon('download')}<h3>${tasks.length?'这个分类里还没有任务':'为喜欢的故事留个位置'}</h3><p>${tasks.length?'切换分类，查看其他下载任务。':'选择电影或剧集资源，把它加入你的下载队列。'}</p><a href="#discover" class="btn primary">发现好内容 ${icon('arrow')}</a></div>`;}
function settingsView(){return heading('给收藏，安一个家。','设置保存目录、下载策略和高分筛选偏好。')+`<div class="settings-grid"><form id="settings-form"><section class="panel"><h2>${icon('folder')} 下载目录</h2><p class="panel-description">${live?'文件将由运行此服务的电脑保存。目录需要位于配置允许的下载根目录内。':'此处保存演示偏好；实际文件保存需运行本地 MVC 版。'}</p><label class="form-field"><span>默认保存目录</span><div class="input-action"><input name="directory" value="${esc(settings.directory)}" placeholder="例如 D:\\Movies\\CineVault" required><button class="btn" type="button" data-action="check-directory">检查目录</button></div><small>${live?'允许的根目录在 appsettings.json 的 AllowedDownloadRoots 中设置。':'在线页面无法直接读写任意本地目录。运行本地版后可指定服务电脑上的保存路径。'}</small></label><div id="directory-result" class="connection-result" role="status"></div><label class="toggle-row"><span>按内容类型归档<small>电影保存至 Movies，剧集保存至 Series 子目录</small></span><input name="organize" type="checkbox" ${settings.organize?'checked':''}></label></section><section class="panel"><h2>${icon('download')} 下载策略</h2><p class="panel-description">控制并行数量与失败后的处理方式。</p><label class="toggle-row"><span>失败时自动重试<small>自动退避后重新下载，直到达到次数上限</small></span><input name="autoRetry" type="checkbox" ${settings.autoRetry?'checked':''}></label><div class="form-row"><label class="form-field"><span>最大重试次数</span><select name="maxRetries">${options([0,1,2,3,4,5],settings.maxRetries,'不重试')}</select></label><label class="form-field"><span>同时下载任务数</span><select name="concurrency">${options([1,2,3,4],settings.concurrency,'')}</select></label></div><label class="form-field"><span>默认最低评分</span><select name="minRating">${[0,6,7,7.5,8,8.5,9,9.5].map(x=>`<option value="${x}" ${Number(settings.minRating)===x?'selected':''}>${x===0?'不限':x.toFixed(1)+' 分及以上'}</option>`).join('')}</select><small>保存后会同步更新资源发现页的默认筛选条件。</small></label><div id="settings-error" class="form-error" role="alert"></div><div class="form-actions"><button class="btn" type="button" data-action="restore-settings">恢复默认</button><button class="btn primary" type="submit">${icon('check')}保存设置</button></div></section></form><div><section class="panel"><h2>${icon('server')} 本地服务</h2><p class="panel-description">${live?'C# 后端已连接，抓取和下载将由本机服务执行。':'Sites 提供交互演示。运行配套 C# 服务可开启真实抓取与下载。'}</p><span class="status-pill">${icon(live?'check':'info')}${live?'MVC 服务在线':'当前为演示模式'}</span><div class="source-status">架构 <strong>C# · ASP.NET Core MVC</strong><br>下载 <strong>HTTP / HTTPS 直链</strong><br>保存 <strong>服务电脑的指定目录</strong><br>队列 <strong>本地 JSON 持久化</strong></div><a class="btn primary" href="/CineVault-MVC.zip" download>${icon('download')}下载 MVC 项目</a><button class="btn" data-action="help" style="margin-top:10px">查看启动说明 ${icon('arrow')}</button></section><section class="panel"><h2>${icon('link')} 资源来源</h2><p class="panel-description">目标网站<br><a class="resource-link" href="https://www.gying.net/" target="_blank" rel="noopener noreferrer">https://www.gying.net/ ${icon('external')}</a></p><p class="security-note">抓取仅读取公开页面。源站不可达、页面结构变化或需要 JavaScript 时会显示错误，可在本地配置解析规则。</p><button class="btn small" data-action="source">查看来源状态</button></section></div></div>`;}
function safeUrl(s){try{const u=new URL(s);return ['http:','https:'].includes(u.protocol)||u.protocol==='magnet:'&&/^urn:btih:(?:[a-f0-9]{40}|[a-z2-7]{32})$/i.test(u.searchParams.get('xt')||'')?u.href:'#';}catch{return '#';}}
function openModal(html,wide=false){previousFocus=document.activeElement;$('#overlay-root').innerHTML=`<div class="overlay"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${modalMovie?'资源详情':'操作面板'}"><button class="icon-btn close" data-action="close-modal" aria-label="关闭">${icon('close')}</button>${html}</section></div>`;hydrate();$('.modal .close').focus();}
function closeModal(){ $('#overlay-root').innerHTML='';modalMovie=null;previousFocus?.focus(); }
function showDetails(id){const m=media.find(x=>x.id===id);if(!m)return;modalMovie=m;const resources=m.isDemo?m.qualities.map((q,i)=>({id:'demo-'+i,name:`${m.originalTitle||m.title}.${m.year}.${q}.${q==='4K'?'REMUX':'BluRay'}`,quality:q,size:q==='4K'?'18.6 GB · 示例':'3.8 GB · 示例',protocol:'示例直链'})):m.resources||[];
openModal(`<div class="detail-head"><div class="detail-poster">${m.poster?`<img src="${esc(m.poster)}" alt="${esc(m.title)}海报">`:''}</div><div class="detail-summary"><div class="eyebrow">${m.isDemo?'SAMPLE COLLECTION':'RESOURCE DETAILS'}</div><h2>${esc(m.title)}</h2><p class="original-title">${esc(m.originalTitle)}</p><div class="muted">${esc(m.year||'未知年份')} · ${esc(m.genres.join(' / ')||'未分类')} · ${esc(m.duration||'时长未知')}</div><div class="detail-scores"><div class="detail-score"><strong>${m.rating?m.rating.toFixed(1):'—'}</strong>${m.isDemo?'豆瓣（示例）':esc(m.ratingSource||'源站评分')}</div><div class="detail-score"><strong>${m.imdb?m.imdb.toFixed(1):'—'}</strong>IMDb${m.isDemo?'（示例）':''}</div></div></div></div><p class="detail-description">${esc(m.description||'源站未提供简介。')}</p>${m.isDemo?`<div class="notice warning">${icon('info')}<span>示例资源没有真实下载地址。加入队列仅演示状态，不会下载此影片。</span></div>`:''}${!m.isDemo?`<button class="btn small" data-find-magnets="${esc(m.id)}">搜索磁力资源 · 优先 4K 中字</button>`:''}<div class="resource-heading"><span>可选资源 <small class="muted">${resources.length} 个版本</small></span><a href="${esc(safeUrl(m.sourceUrl))}" target="_blank" rel="noopener noreferrer" class="resource-link">${m.isDemo?'源站入口':'原始页面'} ${icon('external')}</a></div><form id="resource-form">${resources.map((r,i)=>`<label class="resource-option"><input type="radio" name="resource" value="${esc(r.id)}" ${!i?'checked':''}><div class="resource-info"><strong>${esc(r.name||r.quality||'下载资源')}</strong><small>${esc(r.quality||'未知画质')} · ${esc(r.protocol||'HTTP')} ${r.size?'· '+esc(r.size):''}</small>${!m.isDemo?`<a class="resource-link" href="${esc(safeUrl(r.url))}" target="_blank" rel="noopener noreferrer">查看链接 ${icon('external')}</a>`:''}</div>${!m.isDemo?`<button type="button" class="icon-btn" data-copy="${esc(r.url)}" aria-label="复制资源链接">${icon('copy')}</button>`:`<span>演示</span>`}</label>`).join('')||'<p class="muted">此来源尚无下载文件。Internet Archive 请从「多来源检索」读取文件列表；TMDB 和 IMDb 仅提供资料。</p>'}<label class="form-field"><span>保存目录</span><input name="directory" value="${esc(settings.directory)}" required><small>${live?'本地服务将检查目录权限与允许的保存范围。':'演示路径，不会写入本地磁盘。'}</small></label><div id="resource-error" class="form-error" role="alert"></div><div class="modal-actions"><span>${icon('info')} ${m.isDemo?'队列状态会在当前浏览器保留':'HTTP 由内置服务下载；磁力链接由 qBittorrent 下载'}</span><button class="btn primary" type="submit" ${!resources.length?'disabled':''}>${icon('download')}${m.isDemo?'模拟加入下载队列':'加入下载队列'}</button></div></form>`,true);}
function sourceModal(){modalMovie=null;openModal(`<div class="eyebrow">SOURCE CONNECTION</div><h2>资源来源与抓取</h2><p class="muted">通过本地服务读取公开页面，再根据评分与类型筛选内容。</p><div class="source-status">目标网站 <a class="resource-link" href="https://www.gying.net/" target="_blank" rel="noopener noreferrer">www.gying.net ${icon('external')}</a><br>当前状态 <strong>${live?'本地服务已连接':'Sites 交互演示'}</strong><br>抓取模式 <strong>${live?(respectRobots?'检查源站访问规则':'直接请求页面 · 跳过 robots.txt'):'交互演示'}</strong><br>上次更新 <strong>${lastSync?new Date(lastSync).toLocaleString('zh-CN'):'尚未执行真实抓取'}</strong></div><div class="notice warning">${icon('info')}<span>${live?esc(crawlError||'抓取会读取首页与配置的列表页。源站无法访问或页面需要脚本时，服务会返回明确错误。'):'源站在本次检查中访问超时，尚未验证真实页面解析。在线演示不发起抓取，也不提供未经验证的影片下载链接。'}</span></div><p class="muted">本地版支持 JSON-LD 及可配置的 HTML 解析规则；站点返回的评分与资源才会进入真实资源库。</p><div class="modal-actions"><button class="btn" data-action="help">${icon('help')}运行本地版</button><button class="btn primary" data-action="${live?'crawl-now':'close-modal'}">${live?'开始抓取':'了解了'} ${icon('arrow')}</button></div>`);}
function help(){modalMovie=null;openModal(`<div class="eyebrow">A LITTLE GUIDE</div><h2>把好故事，留在身边。</h2><p class="muted">在线演示体验操作流程；本地 MVC 版负责真实抓取和保存文件。</p><ol class="help-steps"><li><strong>发现与比较</strong><br>按片名、类型、评分、年份、画质筛选；点卡片右上角「+」比较最多四部内容。</li><li><strong>下载完整 C# 项目</strong><br>Docker 本地部署请阅读项目 README。也可安装 .NET 10 SDK，在 server 目录执行：<div class="code-block">dotnet run --urls http://localhost:5188</div></li><li><strong>打开本地工作台</strong><br>访问 <a class="resource-link" href="http://localhost:5188" target="_blank" rel="noopener noreferrer">http://localhost:5188</a>，设置保存目录并刷新资源。Docker 的下载根目录为 <code>/downloads</code>（映射至宿主机配置目录）；直接运行时默认为 <code>server/App_Data/downloads</code>；其他目录需在 appsettings.json 中加入允许列表。</li><li><strong>选择资源并下载</strong><br>本地任务支持暂停、继续、取消、自动退避重试与手动重试。磁力与网盘链接可查看及复制，直接下载器只处理 HTTP/HTTPS 文件链接。</li></ol><div class="notice">${icon('info')}<span>源站目前无法验证，解析适配器可能需要根据实际页面调整。项目 README 提供配置、API 与测试说明。</span></div><div class="modal-actions"><span>ASP.NET Core MVC · .NET 10</span><a class="btn primary" href="/CineVault-MVC.zip" download>${icon('download')}下载 MVC 项目</a></div>`);}
function manualDownload(){modalMovie=null;if(!live){openModal(`<div class="eyebrow">NEW DOWNLOAD</div><h2>开始一项下载</h2><p class="muted">在线版可从示例片单创建模拟任务。真实 HTTP 链接下载需要运行本地 MVC 版。</p><div class="modal-actions"><button class="btn" data-action="help">运行本地版</button><a class="btn primary" href="#discover" data-action="close-modal">选择示例资源 ${icon('arrow')}</a></div>`);return;}openModal(`<h2>新建下载任务</h2><p class="muted">添加 HTTP / HTTPS 文件链接或 magnet: 磁力链接；磁力任务需已配置 qBittorrent。</p><form id="manual-form"><label class="form-field"><span>资源名称</span><input name="title" required maxlength="120" placeholder="例如：公开授权影片"></label><label class="form-field"><span>下载链接</span><input name="url" type="url" required placeholder="https://example.org/movie.mp4"></label><label class="form-field"><span>保存目录</span><input name="directory" required value="${esc(settings.directory)}"></label><div id="manual-error" class="form-error" role="alert"></div><div class="modal-actions"><span>文件名由服务安全生成</span><button type="submit" class="btn primary">${icon('download')}加入队列</button></div></form>`);}
async function addResource(form){const m=modalMovie;if(!m)return;const data=new FormData(form),directory=String(data.get('directory')||'').trim();if(!directory){$('#resource-error').textContent='请输入保存目录';return;}const button=form.querySelector('button[type=submit]');button.disabled=true;try{if(m.isDemo){const q=m.qualities[Number(String(data.get('resource')).split('-')[1])]||'1080P';if(tasks.some(t=>t.mediaId===m.id&&t.quality===q&&!['Failed','Cancelled','Completed'].includes(t.status)))throw new Error('该资源已在下载队列中');tasks.unshift({id:crypto.randomUUID(),mediaId:m.id,title:m.title,quality:q,fileName:`${m.originalTitle||m.title}.${m.year}.${q}.mkv`,directory:directory+(settings.organize?(m.type==='tv'?'\\Series':'\\Movies'):''),isDemo:true,status:'Queued',progress:0,attempts:0,maxRetries:settings.maxRetries,autoRetry:settings.autoRetry,createdAt:new Date().toISOString(),failOnce:q==='4K'});save('tasks',tasks);}else{const t=await api('/downloads','POST',{mediaId:m.id,resourceId:data.get('resource'),directory});tasks.unshift(t);}closeModal();toast(m.isDemo?'已加入模拟队列；不会写入文件':'已加入下载队列');location.hash='downloads';if(view==='downloads')render();}catch(e){$('#resource-error').textContent=e.message;button.disabled=false;}}
async function taskAction(id,action){const t=tasks.find(x=>x.id===id);if(!t)return;try{if(!t.isDemo){const updated=await api(`/downloads/${encodeURIComponent(id)}/${action}`,'POST',{});tasks=tasks.map(x=>x.id===id?updated:x);}else{if(action==='pause')t.status='Paused';if(action==='resume'){t.status='Queued';t.error='';}if(action==='cancel'){t.status='Cancelled';t.error='';}if(action==='retry'){t.status='Queued';t.progress=0;t.attempts=0;t.failOnce=false;t.error='';}if(action==='fail'){t.status='Failed';t.error='模拟：网络连接中断。可点击重试继续体验。';t.failOnce=false;}}save('tasks',tasks.filter(t=>t.isDemo));render();if(view==='discover')renderCards();}catch(e){toast(e.message,true);}}
async function crawl(){if(!live){sourceModal();return;}if(isCrawling)return;closeModal();isCrawling=true;crawlError='';crawlFailure=null;render();renderCards();try{const r=await api('/crawl','POST',{});media=r.items;lastSync=r.updatedAt;selected=selected.filter(id=>media.some(m=>m.id===id));if(r.warnings?.length)crawlError=r.warnings.join('；');toast(`抓取完成，收录 ${media.length} 部内容`);}catch(e){crawlError=e.message;crawlFailure=e.code?{code:e.code,hint:e.hint,robotsUrl:e.robotsUrl,rule:e.rule}:null;toast((e.code==='robots_disallowed'?'源站限制自动抓取：':'抓取未完成：')+e.message,true);}finally{isCrawling=false;render();renderCards();}}
async function saveSettings(form){const d=new FormData(form);try{let next=validateSettings({directory:String(d.get('directory')),maxRetries:Number(d.get('maxRetries')),concurrency:Number(d.get('concurrency')),minRating:Number(d.get('minRating')),autoRetry:d.has('autoRetry'),organize:d.has('organize')});if(live)next=await api('/settings','PUT',next);settings=next;save('settings',settings);filters.minRating=settings.minRating;toast(live?'设置已保存':'演示偏好已保存');render();}catch(e){$('#settings-error').textContent=e.message;}}
document.addEventListener('click',async e=>{
 const compare=e.target.closest('[data-compare]');if(compare){e.preventDefault();e.stopPropagation();try{selected=toggleCompare(selected,compare.dataset.compare);save('compare',selected);if(view==='compare')render();else{renderCards();renderDock();}}catch(err){toast(err.message,true);}return;}
 const details=e.target.closest('[data-details]');if(details){e.preventDefault();showDetails(details.dataset.details);return;}
 const movie=e.target.closest('[data-movie]');if(movie){showDetails(movie.dataset.movie);return;}
 const type=e.target.closest('[data-type]');if(type){filters.type=type.dataset.type;document.querySelectorAll('[data-type]').forEach(x=>{x.classList.toggle('active',x===type);x.setAttribute('aria-selected',x===type);});renderCards();return;}
 const vs=e.target.closest('[data-view]');if(vs){listView=vs.dataset.view==='list';document.querySelectorAll('[data-view]').forEach(x=>{x.classList.toggle('active',x===vs);x.setAttribute('aria-pressed',x===vs);});renderCards();return;}
 const tf=e.target.closest('[data-task-filter]');if(tf){downloadFilter=tf.dataset.taskFilter;render();return;}
 const ta=e.target.closest('[data-task-action]');if(ta){await taskAction(ta.dataset.task,ta.dataset.taskAction);return;}
 const copy=e.target.closest('[data-copy]');if(copy){try{await navigator.clipboard.writeText(copy.dataset.copy);toast('资源链接已复制');}catch{toast('复制失败，请使用资源链接手动复制',true);}return;}
 const a=e.target.closest('[data-action]')?.dataset.action;if(!a){if(e.target.classList.contains('overlay'))closeModal();return;}
 if(a==='close-modal')closeModal();if(a==='help')help();if(a==='source'||a==='crawl'&&!live)sourceModal();if(a==='crawl'&&live)location.hash='sources';if(a==='crawl-now')await crawl();if(a==='manual-download')manualDownload();
 if(a==='reset'){filters={search:'',type:'',genre:'',minRating:0,year:'',quality:'',sort:'rating'};render();renderCards();}
 if(a==='high-rated'){filters.minRating=9;filters.type='';filters.search='';filters.genre='';filters.year='';filters.quality='';render();renderCards();$('#library')?.scrollIntoView({behavior:'smooth',block:'start'});}
 if(a==='clear-compare'){selected=[];save('compare',selected);render();renderCards();}
 if(a==='retry-all'){const failed=tasks.filter(t=>t.status==='Failed');if(!failed.length)toast('没有需要重试的失败任务');for(const t of failed)await taskAction(t.id,'retry');}
 if(a==='clear-completed'){try{if(live)await api('/downloads/finished','DELETE');tasks=tasks.filter(t=>!['Completed','Cancelled'].includes(t.status));save('tasks',tasks.filter(t=>t.isDemo));render();toast('已清理结束记录，已下载的文件会保留');}catch(err){toast(err.message,true);}}
 if(a==='restore-settings'){const d=live?await api('/defaults').catch(()=>settings):DEFAULT_SETTINGS;const f=$('#settings-form');for(const[k,v]of Object.entries(d)){const n=f.elements.namedItem(k);if(n){if(n.type==='checkbox')n.checked=Boolean(v);else n.value=v;}}toast('已填入默认值，点击保存后生效');}
 if(a==='check-directory'){const d=$('#settings-form').elements.directory.value;$('#directory-result').textContent=live?'正在检查…':'演示模式仅保存路径偏好，不检查本地磁盘权限。';if(live){try{const r=await api('/directory/check','POST',{directory:d});$('#directory-result').textContent=`目录可写：${r.directory}`;}catch(err){$('#directory-result').textContent=err.message;}}}
});
document.addEventListener('input',e=>{if(e.target.id==='search'){filters.search=e.target.value;renderCards();}if(e.target.dataset.filter==='minRating'){filters.minRating=e.target.value;$('#rating-output').textContent=Number(filters.minRating).toFixed(1)+'+';renderCards();}});
document.addEventListener('change',e=>{const k=e.target.dataset.filter;if(k){filters[k]=e.target.value;renderCards();}});
document.addEventListener('submit',async e=>{if(['resource-form','settings-form','manual-form'].includes(e.target.id))e.preventDefault();if(e.target.id==='resource-form')await addResource(e.target);if(e.target.id==='settings-form')await saveSettings(e.target);if(e.target.id==='manual-form'){const d=new FormData(e.target),b=e.target.querySelector('button[type=submit]');b.disabled=true;try{const t=await api('/downloads','POST',Object.fromEntries(d));tasks.unshift(t);closeModal();location.hash='downloads';render();toast('已加入下载队列');}catch(err){$('#manual-error').textContent=err.message;b.disabled=false;}}});
document.addEventListener('keydown',e=>{if($('.modal')){if(e.key==='Escape'){closeModal();return;}if(e.key==='Tab'){const focusable=[...$('.modal').querySelectorAll('button:not(:disabled),a[href],input:not(:disabled),select:not(:disabled)')];const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}return;}if(['Enter',' '].includes(e.key)&&e.target.matches('[data-movie]')){e.preventDefault();showDetails(e.target.dataset.movie);}});
$('#mobile-menu').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));$('#service-button').addEventListener('click',()=>location.hash='settings');
window.addEventListener('hashchange',()=>{closeModal();render();renderCards();window.scrollTo(0,0);if(live)initializeSourceSearch({view,catalogueEmpty:!media.length});});
function refreshTaskUI(){updateCounts();if(view==='downloads'){$('#download-list').innerHTML=downloadCards();document.querySelectorAll('[data-task-filter] span').forEach(e=>{const f=e.parentElement.dataset.taskFilter;e.textContent=f==='active'?tasks.filter(t=>['Queued','Downloading','Paused','Retrying'].includes(t.status)).length:f?tasks.filter(t=>t.status===f).length:tasks.length;});hydrate();}if(view==='discover'){$('#stat-active').innerHTML=tasks.filter(t=>['Downloading','Queued','Retrying'].includes(t.status)).length+'<small style="font-size:10px;font-weight:400;margin-left:4px">个</small>';$('#stat-complete').innerHTML=tasks.filter(t=>t.status==='Completed').length+'<small style="font-size:10px;font-weight:400;margin-left:4px">个</small>';}}
if(serverMode){media=[];tasks=[];selected=[];}
let polling=false;setInterval(async()=>{if(live){if(polling)return;polling=true;try{tasks=await api('/downloads');refreshTaskUI();}catch{}finally{polling=false;}return;}let dirty=false;let active=tasks.filter(t=>t.status==='Downloading').length;for(const t of tasks){if(t.status==='Retrying'&&Date.now()>t.retryAt){t.status='Queued';t.error='';dirty=true;}if(t.status==='Queued'&&active<settings.concurrency){t.status='Downloading';active++;dirty=true;}if(t.status!=='Downloading')continue;t.progress=Math.min(100,(t.progress||0)+4);dirty=true;if(t.failOnce&&t.progress>=32){t.failOnce=false;if(t.autoRetry&&t.attempts<t.maxRetries){t.attempts++;t.status='Retrying';t.retryAt=Date.now()+4000;t.progress=0;t.error='模拟：连接中断，4 秒后自动重试。';}else{t.status='Failed';t.error='模拟：连接中断，点击重试可继续。';}active--;}else if(t.progress>=100){t.status='Completed';t.error='';active--;}}if(dirty){save('tasks',tasks);refreshTaskUI();}},1200);
configureSourceSearch({api,toast,refresh:()=>{if(view==='sources'||view==='discover'){render();renderCards();}},onResults:(items,context={})=>{const ids=new Set(items.map(m=>m.id));const fresh=items.map(m=>{const old=media.find(x=>x.id===m.id);return old&&!m.resources.length?{...m,resources:old.resources,qualities:old.qualities}:m;});media=[...fresh,...media.filter(m=>!ids.has(m.id))];if(items.length){lastSync=new Date().toISOString();if(context.mode==='latest')filters={search:'',type:'',genre:'',minRating:0,year:'',quality:'',sort:'latest'};}},onResource:item=>{media=media.map(m=>m.id===item.id?item:m);showDetails(item.id);}});
render();renderCards();hydrate();
async function connect(){try{const health=await api('/health');if(health.application!=='CineVault')return;respectRobots=health.respectRobotsTxt!==false;live=true;const r=await Promise.all([api('/settings'),api('/media'),api('/downloads'),loadSourceOptions()]);settings=r[0];media=r[1].items;lastSync=r[1].updatedAt;tasks=r[2];selected=selected.filter(id=>media.some(m=>m.id===id));filters.minRating=settings.minRating;render();renderCards();await initializeSourceSearch({view,catalogueEmpty:!media.length});}catch(e){if(serverMode){toast('服务连接失败：'+e.message,true);}}}
connect();
